  "/": "<!doctype html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"description\" content=\"Estado operativo de los servicios públicos de Seismik.\">\n  <meta name=\"robots\" content=\"noindex\">\n  <title>Estado del servicio · Seismik</title>\n  <link rel=\"icon\" href=\"/favicon.ico\" sizes=\"any\">\n  <link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/assets/favicon-32.png\">\n  <link rel=\"apple-touch-icon\" href=\"/assets/apple-touch-icon.png\">\n  <link rel=\"stylesheet\" href=\"/styles.css?v=__ASSET_VERSION__\">\n  <link rel=\"stylesheet\" href=\"/logo.css?v=__ASSET_VERSION__\">\n  <link rel=\"stylesheet\" href=\"/status.css?v=__ASSET_VERSION__\">\n  <script src=\"/status.js?v=__ASSET_VERSION__\" defer></script>\n<link rel=\"stylesheet\" href=\"/footer.css?v=__ASSET_VERSION__\">\n</head>\n<body>\n  <main class=\"utility-page container\">\n    <a class=\"brand\" href=\"https://seismik.org/\" aria-label=\"Ir a Seismik\"><img class=\"brand-logo\" src=\"/assets/seismik_logo.webp\" width=\"32\" height=\"32\" alt=\"\">SEISMIK <span class=\"brand-tag\">ESTADO</span></a>\n    <p class=\"eyebrow\">Estado público</p>\n    <h1>Servicios de Seismik</h1>\n    <p class=\"lead\">Esta página consulta el borde de Seismik y la disponibilidad real de la API. No muestra métricas internas, datos de personas ni credenciales.</p>\n    <section class=\"status-summary\" aria-live=\"polite\">\n      <span class=\"status-dot checking\" aria-hidden=\"true\"></span>\n      <div><strong id=\"overall-status\">Comprobando servicios…</strong><p id=\"checked-at\" class=\"fine-print\">Actualización automática cada 60 segundos.</p></div>\n    </section>\n    <section class=\"status-grid\" aria-label=\"Servicios\">\n      <article class=\"status-card\"><div><h2>API pública</h2><p>Registro, consulta de eventos y API para desarrolladores.</p></div><span id=\"api-state\" class=\"state checking\">Comprobando</span></article>\n      <article class=\"status-card\"><div><h2>Sitio web</h2><p>seismik.org y sus páginas públicas.</p></div><span id=\"web-state\" class=\"state checking\">Comprobando</span></article>\n      <article class=\"status-card\"><div><h2>Portal de desarrolladores</h2><p>devs.seismik.org, autenticación y claves API.</p></div><span id=\"developers-state\" class=\"state checking\">Comprobando</span></article>\n    </section>\n    <section class=\"status-history\" aria-labelledby=\"history-title\">\n      <h2 id=\"history-title\">Historial de disponibilidad</h2>\n      <p class=\"fine-print\">Últimos 30 días · Comprobaciones cada minuto · Fechas en UTC. Los periodos sin registros no cuentan como disponibilidad.</p>\n      <div id=\"history\" aria-live=\"polite\"><p class=\"fine-print\">Cargando historial…</p></div>\n      <p class=\"history-legend fine-print\"><span class=\"legend-ok\">● Sin fallos registrados</span> <span class=\"legend-degraded\">● Con fallos</span> <span>● Sin registros</span></p>\n    </section>\n    <p class=\"fine-print\">Un estado degradado significa que una comprobación pública no respondió. No implica por sí solo que una alerta sísmica se haya perdido.</p>\n    <div class=\"actions\"><a class=\"button secondary\" href=\"https://seismik.org/\">Ir a Seismik</a><button id=\"refresh\" class=\"button\" type=\"button\">Actualizar ahora</button></div>\n  </main>\n  <script src=\"/site.js?v=__ASSET_VERSION__\" defer></script>\n<footer class=\"site-footer\"><div class=\"container footer-bottom\"><span>© 2026 Seismik</span></div></footer>\n</body>\n</html>\n"
